{{-- scouting-area.tsx Pager. Variabili: $total, $size, $page, $setter (metodo Livewire) e $label (nome accessibile della navigazione). --}}
@php($lastPage = max(1, (int) ceil($total / max(1, $size))))
<div class="census-pager" role="navigation" aria-label="{{ $label }}"><span>{{ $total }} risultati · pagina {{ $page }} di {{ $lastPage }}</span><div class="crm-actions">@if ($cursor ?? false)<button type="button" class="crm-btn secondary" wire:click="prevPage" @disabled($page <= 1)>Precedente</button><button type="button" class="crm-btn secondary" wire:click="nextPage(@js($nextCursor))" @disabled($nextCursor === null || $page >= $lastPage)>Successiva</button>@else<button type="button" class="crm-btn secondary" wire:click="{{ $setter }}({{ $page - 1 }})" @disabled($page <= 1)>Precedente</button><button type="button" class="crm-btn secondary" wire:click="{{ $setter }}({{ $page + 1 }})" @disabled($page >= $lastPage)>Successiva</button>@endif</div></div>
